// categorias.component.ts
import { Component } from '@angular/core';
import { PiensoService } from '../services/pienso.service';

@Component({
  selector: 'app-categorias',
  templateUrl: './categorias.component.html',
  styleUrls: ['./categorias.component.css']
})
export class CategoriasComponent {
  categoriaSeleccionada: string = ''; // Variable para almacenar la categoría seleccionada

  constructor(private piensoService: PiensoService) {}

  // Método para manejar cambios en la categoría seleccionada
  seleccionarCategoria(categoria: string) {
    this.categoriaSeleccionada = categoria;
    this.filtrarProductos(); // Llamar al método de filtrado cuando se selecciona una categoría
  }
}
